from itertools import product
from scipy.optimize import least_squares
t=df['t'];A=df['A'];y=df['dA_dt']
def model(p,kind):
    base = p[0]*np.log(1+p[1]*t)*A**2 + p[2]*np.sin(p[3]*np.sqrt(t))
    if kind=='A': th=p[4]*A
    if kind=='A2': th=p[4]*A**2
    if kind=='At': th=p[4]*A*t
    if kind=='t': th=p[4]*t
    if kind=='expt': th=p[4]*A*np.exp(-p[5]*t)
    if kind=='Aexp': th=p[4]*np.exp(-p[5]*A)
    if kind=='tA2': th=p[4]*t*A**2
    if kind=='sqrt': th=p[4]*A*np.sqrt(t)
    return base+th
best={}
for kind in ['A','A2','At','t','expt','Aexp','tA2','sqrt']:
    bestc=None
    for trial in range(60):
        p0=np.random.randn(6)
        p0[1]=abs(p0[1])+0.1; p0[3]=abs(p0[3])*2
        try:
            r=least_squares(lambda p: model(p,kind)-y, p0)
        except Exception: continue
        if bestc is None or r.cost<bestc.cost: bestc=r
    nmse=np.mean((model(bestc.x,kind)-y)**2)/np.var(y)
